// ── TRIGGER EVALUATION ENGINE ─────────────────────────────────
// Runs the compound trigger logic:
//   Gate 1: renewal <= 90 days (or overdue)
//   Gate 2: at least one champion with Never or Quarterly login
//   Gate 3: last CSM note is >21 days stale

const RENEWAL_WINDOW = 90;
const STALE_NOTE_DAYS = 21;
const DARK_LOGIN = ['Never', 'Quarterly'];
const TODAY = new Date('2026-02-26');

const accounts = $input.all()[0].json.accounts || [];
const contacts = $input.all()[0].json.contacts || [];
const notes    = $input.all()[0].json.notes || [];

// Build lookup maps
const contactsByAccount = {};
contacts.forEach(c => {
  if (!contactsByAccount[c.account_id]) contactsByAccount[c.account_id] = [];
  contactsByAccount[c.account_id].push(c);
});

const latestNoteByAccount = {};
notes.forEach(n => {
  const d = new Date(n.note_date);
  if (!latestNoteByAccount[n.account_id] || d > new Date(latestNoteByAccount[n.account_id].note_date)) {
    latestNoteByAccount[n.account_id] = n;
  }
});

const triggered = [];

accounts.forEach(acct => {
  const renewal = new Date(acct.renewal_date);
  const daysToRenewal = Math.round((renewal - TODAY) / (1000 * 60 * 60 * 24));

  // Gate 1: renewal window
  if (daysToRenewal > RENEWAL_WINDOW) return;

  // Gate 2: dark champion
  const acctContacts = contactsByAccount[acct.account_id] || [];
  const champions = acctContacts.filter(c => c.role_type === 'Champion');
  if (champions.length === 0) return;
  const darkChampions = champions.filter(c => DARK_LOGIN.includes(c.login_frequency));
  if (darkChampions.length === 0) return;

  // Gate 3: stale notes
  const latestNote = latestNoteByAccount[acct.account_id];
  let daysSinceNote = 999;
  let lastNoteText = 'No notes on record';
  if (latestNote) {
    daysSinceNote = Math.round((TODAY - new Date(latestNote.note_date)) / (1000 * 60 * 60 * 24));
    lastNoteText = latestNote.note;
  }
  if (daysSinceNote < STALE_NOTE_DAYS) return;

  // Calculate usage trend
  const usageCols = ['usage_m1_sep','usage_m2_oct','usage_m3_nov','usage_m4_dec','usage_m5_jan','usage_m6_feb_current'];
  const usageVals = usageCols.map(c => acct[c]).filter(v => v != null);
  let usageTrend = 'unknown';
  if (usageVals.length >= 2) {
    const first = usageVals.slice(0, 3).reduce((a,b) => a+b, 0) / 3;
    const last  = usageVals.slice(-3).reduce((a,b) => a+b, 0) / 3;
    usageTrend = last > first * 1.1 ? 'increasing' : (last < first * 0.9 ? 'declining' : 'flat');
  }

  triggered.push({
    account_id:       acct.account_id,
    company_name:     acct.company_name,
    csm_assigned:     acct.csm_assigned,
    mrr:              acct.mrr,
    arr:              acct.arr,
    plan_tier:        acct.plan_tier,
    days_to_renewal:  daysToRenewal,
    renewal_date:     acct.renewal_date,
    nps_score:        acct.nps_score || 'N/A',
    contraction_flag: acct.contraction_flag || false,
    competitor:       acct.competitor_detected || null,
    all_champions:    champions.map(c => c.name).join(', '),
    dark_champions:   darkChampions.map(c => c.name).join(', '),
    dark_champ_count: darkChampions.length,
    total_champ_count:champions.length,
    days_since_note:  daysSinceNote,
    last_note_text:   lastNoteText,
    usage_trend:      usageTrend,
  });
});

if (triggered.length === 0) {
  return [{ json: { status: 'no_triggers', count: 0, date: TODAY.toISOString().split('T')[0] }}];
}

return triggered.map(t => ({ json: t }));

