// Extract Claude's response and build Slack Block Kit payload
const claudeResponse = $input.item.json;
const accountCtx = $('Evaluate Compound Trigger').item.json;

const alertText = claudeResponse.content[0].text;

// Color code by urgency
let color = '#FFC107'; // yellow = <90d
if (accountCtx.days_to_renewal < 0)  color = '#FF0000'; // red = overdue
else if (accountCtx.days_to_renewal < 30) color = '#FF6B35'; // orange = <30d

const slackPayload = {
  text: `Champion Dark Alert: ${accountCtx.company_name}`,
  attachments: [
    {
      color: color,
      text: alertText,
      footer: `GTM Intelligence • ${new Date().toISOString().split('T')[0]} • ${accountCtx.account_id}`,
    }
  ]
};

return {
  json: {
    slackPayload,
    csm_assigned: accountCtx.csm_assigned,
    account_id: accountCtx.account_id,
    company_name: accountCtx.company_name,
    mrr: accountCtx.mrr,
    days_to_renewal: accountCtx.days_to_renewal,
    alert_text: alertText
  }
};

// Log alert to audit trail (Google Sheets or Postgres in production)
const data = $input.item.json;
return {
  json: {
    timestamp: new Date().toISOString(),
    account_id: data.account_id,
    company_name: data.company_name,
    csm_assigned: data.csm_assigned,
    mrr: data.mrr,
    days_to_renewal: data.days_to_renewal,
    alert_sent: true,
    alert_preview: data.alert_text.substring(0, 200)
  }
};
